import { writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { initHash, hash2, hashLeaf } from '../src/hash';
import { ZkTree } from '../src/tree';
import { toHex } from '../src/field';

await initHash();
const leaf = hashLeaf(2n, [1n, 2n, 3n, 4n, 5n, 6n]);
const tree = new ZkTree();
tree.setLeaf(3, hashLeaf(1n, [9n, 9n, 9n, 9n, 9n, 9n]));
tree.setLeaf(5, leaf);

const lines = [
  '// GENERATED by packages/zkdb/scripts/gen-vectors.ts. Do not edit.',
  `pub(crate) global H2_1_2: Field = ${toHex(hash2(1n, 2n))};`,
  `pub(crate) global LEAF_2_123456: Field = ${toHex(leaf)};`,
  `pub(crate) global EMPTY_ROOT: Field = ${toHex(new ZkTree().root)};`,
  `pub(crate) global ROOT_TWO_ROWS: Field = ${toHex(tree.root)};`,
  `pub(crate) global SIBLINGS_ROW5: [Field; 20] = [${tree.siblings(5).map(toHex).join(', ')}];`,
  '',
];
const out = fileURLToPath(new URL('../../../circuits/zkdb/src/test_vectors.nr', import.meta.url));
writeFileSync(out, lines.join('\n'));
console.log('wrote', out);
